blocks.solution:
def best_circular(a):
    best = run = a[0]
    worst = low = a[0]
    for x in a[1:]:
        run = max(x, run + x)
        best = max(best, run)
        low = min(x, low + x)
        worst = min(worst, low)
    if best < 0:
        return best
    return max(best, sum(a) - worst)

def max_subarray(a):
